$ErrorActionPreference = "Stop"

$root = (Get-Location).Path
$ws = Join-Path $root "runtime\workspaces\ahos-autopilot"
$pkg = Join-Path $ws "ahos_core"
$python = Join-Path $root ".venv\Scripts\python.exe"

$modulePath = Join-Path $pkg "ahos\character_memory.py"
$testPath = Join-Path $pkg "tests\test_character_memory.py"
$backlogPath = Join-Path $pkg "STUDIO_BACKLOG.json"
$reportPath = Join-Path $pkg "reports\STUDIO-002-character-memory-proof.json"

# Private story data is intentionally stored OUTSIDE the Git repository.
$privateRoot = Join-Path $root "runtime\private\animation-studio"
$seedPath = Join-Path $privateRoot "character-seed.local.json"
$dbPath = Join-Path $privateRoot "character-memory.db"
$snapshotPath = Join-Path $privateRoot "character-bible.snapshot.local.json"

$patcher = Join-Path $env:TEMP "studio-002-backlog.py"
$builder = Join-Path $env:TEMP "studio-002-build-memory.py"

Write-Host "=== STUDIO-002 CHARACTER BIBLE + CONTINUITY MEMORY ==="
Write-Host "PRIVATE CAST DATA: LOCAL ONLY"
Write-Host "OpenAI API calls: 0"
Write-Host "Paid API spend: USD 0"
Write-Host ""

if (-not (Test-Path $python)) { throw "Python venv not found." }
if (-not (Test-Path $pkg)) { throw "AHOS package not found." }

New-Item -ItemType Directory -Force -Path $privateRoot | Out-Null
New-Item -ItemType Directory -Force -Path (Split-Path $reportPath -Parent) | Out-Null

[IO.File]::WriteAllBytes(
    $modulePath,
    [Convert]::FromBase64String("")
)
[IO.File]::WriteAllBytes(
    $testPath,
    [Convert]::FromBase64String("")
)
[IO.File]::WriteAllBytes(
    $seedPath,
    [Convert]::FromBase64String("")
)
[IO.File]::WriteAllBytes(
    $patcher,
    [Convert]::FromBase64String("")
)
[IO.File]::WriteAllBytes(
    $builder,
    [Convert]::FromBase64String("")
)

$old = $env:PYTHONPATH
Push-Location $pkg
try {
    $env:PYTHONPATH = $pkg

    Write-Host "Running Character Bible focused tests..."
    & $python -m pytest tests\test_character_memory.py -q
    if ($LASTEXITCODE -ne 0) {
        throw "STUDIO-002 focused tests failed."
    }

    Write-Host "Running full AHOS + Studio regression suite..."
    & $python -m pytest -q
    if ($LASTEXITCODE -ne 0) {
        throw "Full regression suite failed."
    }

    Write-Host "Building persistent private Character Bible..."
    & $python $builder $dbPath $seedPath $reportPath
    if ($LASTEXITCODE -ne 0) {
        throw "Character Bible build failed."
    }

    Write-Host "Exporting current private snapshot..."
    & $python -c "from ahos.character_memory import CharacterBibleStore; CharacterBibleStore(r'$dbPath').export_snapshot(r'$snapshotPath')"
    if ($LASTEXITCODE -ne 0) {
        throw "Character Bible snapshot export failed."
    }

    & $python $patcher $backlogPath
    if ($LASTEXITCODE -ne 0) {
        throw "STUDIO-002 backlog update failed."
    }
}
finally {
    Pop-Location
    $env:PYTHONPATH = $old
    Remove-Item $patcher -Force -ErrorAction SilentlyContinue
    Remove-Item $builder -Force -ErrorAction SilentlyContinue
}

# Safety check: private family/cast files must remain outside the nested Git repo.
$repoResolved = [IO.Path]::GetFullPath($ws)
$privateResolved = [IO.Path]::GetFullPath($privateRoot)
if ($privateResolved.StartsWith($repoResolved, [StringComparison]::OrdinalIgnoreCase)) {
    throw "Privacy guard failed: private character data is inside Git repository."
}

git -C $ws add `
    ahos_core/ahos/character_memory.py `
    ahos_core/tests/test_character_memory.py `
    ahos_core/STUDIO_BACKLOG.json `
    ahos_core/reports/STUDIO-002-character-memory-proof.json

$staged = git -C $ws diff --cached --name-only
if ($staged -match "character-seed|character-memory\.db|character-bible\.snapshot") {
    throw "Privacy guard failed: private character data was staged."
}

if ($staged) {
    git -C $ws -c user.name="Miniverse Autopilot" -c user.email="miniverse@local.invalid" `
        commit -m "feat(studio): add persistent character bible memory"
    if ($LASTEXITCODE -ne 0) { throw "git commit failed." }

    git -C $ws push origin HEAD
    if ($LASTEXITCODE -ne 0) { throw "git push failed." }
}

Write-Host ""
Write-Host "=== STUDIO-002 COMPLETE ==="
Write-Host "Persistent Character Bible SQLite: PASS"
Write-Host "Initial core cast: 16"
Write-Host "Versioned character history: PASS"
Write-Host "Locked visual/canon fields: PASS"
Write-Host "Owner override audit trail: PASS"
Write-Host "Relationship graph integrity: PASS"
Write-Host "Canon fact memory: PASS"
Write-Host "Episode continuity event memory: PASS"
Write-Host "Private cast data kept OUTSIDE Git: PASS"
Write-Host "Full regression suite: PASS"
Write-Host "OpenAI API calls: 0"
Write-Host "Paid API spend: USD 0"
Write-Host ""
Write-Host "PRIVATE MEMORY ROOT: $privateRoot"
Write-Host "NEXT: STUDIO-003 Story and Episode Planning Engine."
